function aspi_gallery_upload(array $f): string { if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) throw new RuntimeException('ছবি আপলোড করা যায়নি।'); if(($f['size']??0)>5*1024*1024) throw new RuntimeException('ছবির সর্বোচ্চ সাইজ ৫ MB।'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if($ext===''||!@getimagesize($f['tmp_name']))throw new RuntimeException('শুধু JPG, PNG অথবা WEBP ছবি আপলোড করুন।');$dir=__DIR__.'/../uploads/site';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('আপলোড ফোল্ডার তৈরি করা যায়নি।');$name='gallery-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('ছবি সংরক্ষণ করা যায়নি।');return 'live/uploads/site/'.$name; }
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);try{if(isset($_POST['delete'])){$st=$pdo->prepare('DELETE FROM gallery_images WHERE id=?');$st->execute([$id]);$_SESSION['flash']='গ্যালারির ছবি মুছে ফেলা হয়েছে।';header('Location: gallery.php');exit;}if(isset($_POST['toggle'])){$pdo->prepare("UPDATE gallery_images SET status=IF(status='published','hidden','published') WHERE id=?")->execute([$id]);$_SESSION['flash']='ছবির প্রকাশের অবস্থা পরিবর্তন হয়েছে।';header('Location: gallery.php');exit;}$title=trim((string)($_POST['title']??''));$alt=trim((string)($_POST['alt_text']??''));$status=($_POST['status']??'published')==='hidden'?'hidden':'published';$sort=(int)($_POST['sort_order']??0);$existing=trim((string)($_POST['existing_image']??''));$image=$existing;if(!empty($_FILES['image_file']['name']))$image=aspi_gallery_upload($_FILES['image_file']);if($image==='')throw new RuntimeException('একটি ছবি নির্বাচন করুন।');if($id){$st=$pdo->prepare('UPDATE gallery_images SET title=?,image_path=?,alt_text=?,status=?,sort_order=? WHERE id=?');$st->execute([$title,$image,$alt,$status,$sort,$id]);$_SESSION['flash']='গ্যালারির ছবি আপডেট হয়েছে।';}else{$st=$pdo->prepare('INSERT INTO gallery_images(title,image_path,alt_text,status,sort_order) VALUES(?,?,?,?,?)');$st->execute([$title,$image,$alt,$status,$sort]);$_SESSION['flash']='নতুন ছবি গ্যালারিতে যোগ হয়েছে।';}header('Location: gallery.php');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'ডেটাবেজে কাজটি সম্পন্ন হয়নি। upgrade.sql Import করা আছে কি না যাচাই করুন।';}}
$editing=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM gallery_images WHERE id=?');$st->execute([(int)$_GET['edit']]);$editing=$st->fetch()?:null;}$tableReady=true;try{
 $pdo->exec("INSERT INTO gallery_images(title,image_path,alt_text,status,sort_order) SELECT 'আমাদের ক্যাম্পাস','assets/campus-1.webp','আসহাব সিরাজ পলিটেকনিক ইনস্টিটিউট ক্যাম্পাস','published',10 WHERE NOT EXISTS(SELECT 1 FROM gallery_images WHERE image_path='assets/campus-1.webp')");
 $pdo->exec("INSERT INTO gallery_images(title,image_path,alt_text,status,sort_order) SELECT 'প্রশিক্ষণ কার্যক্রম','assets/campus-2.webp','প্রশিক্ষণ কার্যক্রম','published',20 WHERE NOT EXISTS(SELECT 1 FROM gallery_images WHERE image_path='assets/campus-2.webp')");
 $pdo->exec("INSERT INTO gallery_images(title,image_path,alt_text,status,sort_order) SELECT 'ল্যাব ও ব্যবহারিক শিক্ষা','assets/campus-3.webp','ল্যাব ও ব্যবহারিক শিক্ষা','published',30 WHERE NOT EXISTS(SELECT 1 FROM gallery_images WHERE image_path='assets/campus-3.webp')");
 $pdo->exec("INSERT INTO gallery_images(title,image_path,alt_text,status,sort_order) SELECT 'প্রতিষ্ঠানের পরিবেশ','assets/campus-5.jpg','প্রতিষ্ঠানের পরিবেশ','published',40 WHERE NOT EXISTS(SELECT 1 FROM gallery_images WHERE image_path='assets/campus-5.jpg')");
 $rows=$pdo->query('SELECT * FROM gallery_images ORDER BY sort_order,id DESC')->fetchAll();
}catch(Throwable $e){$rows=[];$tableReady=false;}require __DIR__.'/_head.php';?>
